#!/usr/bin/env node
/**
 * Upload public/media/field-videos to Supabase Storage.
 *
 * The field videos are 226 MB across 35 files. Git carries that into every
 * clone forever and handles binaries badly, so they live in the `site-media`
 * bucket instead and are reached through the /media/field-videos/:file redirect
 * in next.config.js. The paths in the source never change, which matters
 * because two of the seventeen files referencing them are generated by
 * `npm run sync:el-*` and would lose any edit on the next build.
 *
 * The files stay on disk and are gitignored, so a fresh clone will not have
 * them. To repopulate from a machine that does:
 *
 *   node scripts/upload-field-videos.mjs            # upload anything missing
 *   node scripts/upload-field-videos.mjs --force    # re-upload everything
 *   node scripts/upload-field-videos.mjs --check    # report drift, upload none
 *
 * Needs NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY in .env.local.
 */
import fs from "node:fs";
import path from "node:path";
import dotenv from "dotenv";
import { createClient } from "@supabase/supabase-js";

dotenv.config({ path: path.resolve(process.cwd(), ".env.local") });

const BUCKET = "site-media";
const PREFIX = "field-videos";
const LOCAL_DIR = path.join(process.cwd(), "public", "media", "field-videos");

const force = process.argv.includes("--force");
const checkOnly = process.argv.includes("--check");

const url = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL;
const key = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!url || !key) {
  console.error(
    "Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY. " +
      "Both live in .env.local; the service key is required because uploading " +
      "is a privileged operation.",
  );
  process.exit(1);
}

const supabase = createClient(url, key);

/** Everything already in the bucket, by filename. */
async function remoteFiles() {
  const seen = new Map();
  let offset = 0;
  // list() pages at 100 by default and silently truncates, which would make
  // "already uploaded" wrong for a set this size.
  for (;;) {
    const { data, error } = await supabase.storage
      .from(BUCKET)
      .list(PREFIX, { limit: 100, offset });
    if (error) throw new Error(`listing ${BUCKET}/${PREFIX}: ${error.message}`);
    if (!data?.length) break;
    for (const item of data) seen.set(item.name, item.metadata?.size ?? null);
    if (data.length < 100) break;
    offset += data.length;
  }
  return seen;
}

async function main() {
  if (!fs.existsSync(LOCAL_DIR)) {
    console.error(
      `No ${LOCAL_DIR}. The videos are gitignored, so a fresh clone will not ` +
        "have them; copy them from a machine that does before uploading.",
    );
    process.exit(1);
  }

  const local = fs
    .readdirSync(LOCAL_DIR)
    .filter((f) => f.toLowerCase().endsWith(".mp4"))
    .sort();
  const remote = await remoteFiles();

  const missing = local.filter((f) => !remote.has(f));
  const onlyRemote = [...remote.keys()].filter((f) => !local.includes(f));

  console.log(`local ${local.length}  remote ${remote.size}`);
  if (missing.length) console.log(`  not yet uploaded: ${missing.length}`);
  if (onlyRemote.length) {
    // Not deleted automatically: something else may still reference them, and
    // an unexpected delete is far more expensive than an unused file.
    console.log(
      `  in the bucket but not on disk: ${onlyRemote.join(", ")}` +
        "\n  (left alone; remove by hand if they are genuinely dead)",
    );
  }

  if (checkOnly) return;

  const queue = force ? local : missing;
  if (!queue.length) {
    console.log("Nothing to upload.");
    return;
  }

  let done = 0;
  const failed = [];
  for (const name of queue) {
    const body = fs.readFileSync(path.join(LOCAL_DIR, name));
    const { error } = await supabase.storage
      .from(BUCKET)
      .upload(`${PREFIX}/${name}`, body, {
        contentType: "video/mp4",
        upsert: true,
      });
    if (error) {
      failed.push(`${name}: ${error.message}`);
      process.stdout.write("x");
    } else {
      done += 1;
      process.stdout.write(".");
    }
  }
  process.stdout.write("\n");

  console.log(`Uploaded ${done} of ${queue.length}.`);
  if (failed.length) {
    console.log("Failures:");
    for (const f of failed) console.log(`  ${f}`);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
